using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using ProMaxx2.QA.Domain.Identity;using ProMaxx2.QA.Domain.Projects;using ProMaxx2.QA.Domain.Releases;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class ReleaseConfiguration:IEntityTypeConfiguration<Release>{public void Configure(EntityTypeBuilder<Release>b){b.ToTable("Releases");b.HasKey(x=>x.ReleaseId);b.Property(x=>x.ReleaseId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.ReleaseCode).HasMaxLength(100).IsRequired();b.HasIndex(x=>new{x.ProjectId,x.ReleaseCode}).IsUnique();b.Property(x=>x.Version).HasMaxLength(50).IsRequired();b.Property(x=>x.ReleaseType).HasMaxLength(50);b.Property(x=>x.Status).HasMaxLength(30).IsRequired();b.Property(x=>x.CreatedAt).HasPrecision(0);b.Property(x=>x.UpdatedAt).HasPrecision(0);b.HasOne<Project>().WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.ReleaseOwnerUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class BuildConfiguration:IEntityTypeConfiguration<Build>{public void Configure(EntityTypeBuilder<Build>b){b.ToTable("Builds");b.HasKey(x=>x.BuildId);b.Property(x=>x.BuildId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.BuildNumber).HasMaxLength(100).IsRequired();b.HasIndex(x=>new{x.ReleaseId,x.BuildNumber}).IsUnique();b.Property(x=>x.ApplicationVersion).HasMaxLength(100);b.Property(x=>x.PackageVersion).HasMaxLength(100);b.Property(x=>x.CommitReference).HasMaxLength(200);b.Property(x=>x.BuildDate).HasPrecision(0);b.Property(x=>x.Status).HasMaxLength(30).IsRequired();b.Property(x=>x.CreatedAt).HasPrecision(0);b.HasOne(x=>x.Release).WithMany(x=>x.Builds).HasForeignKey(x=>x.ReleaseId).OnDelete(DeleteBehavior.Restrict);}}
